/* UX flows. Persistence and authentication are provided only by SaiServices. */
const api = window.SaiServices;
const $ = selector => document.querySelector(selector);
let catalog = {opportunities:[],providers:[],experiences:[],interests:[],opportunityTypes:[]};
let user = null, savedItems = [], activeInterest = 'الكل', authMode = 'login', returnTo = 'home';
let pendingAction = null, catalogVersion = 0, accountVersion = 0, catalogReady = false;
const pendingSaves=new Set();
let experienceDraft = {title:'',body:'',field:'',topic:''};
const dialog = $('#detail-dialog');
const normal = value => String(value || '').normalize('NFKC').replace(/[\u064B-\u065F\u0670\u0640]/g,'').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').toLowerCase();
const paragraphs = text => String(text || '').split('\n\n').map(p=>`<p class="preserve-text">${esc(p)}</p>`).join('');
function safeURL(value){try{const url=new URL(value);return ['https:','http:'].includes(url.protocol)?url.href:null;}catch{return null;}}
function external(value,label){const url=safeURL(value);return url?`<a class="button outline" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ${icon('arrow')}</a>`:'<p class="muted">الرابط الرسمي غير متاح حاليًا.</p>';}
function tags(values){return (values || []).map(v=>`<span class="badge">${esc(v)}</span>`).join('');}
function status(selector,text,error=false){const el=$(selector);if(!el)return;el.hidden=!text;el.textContent=text;el.classList.toggle('is-error',error);}
function show(title,body,wide=false){dialog.dataset.revision=String(show.revision=(show.revision||0)+1);delete dialog.dataset.outcomeId;delete dialog.dataset.opportunityId;delete dialog.dataset.contentKind;delete dialog.dataset.contentId;delete dialog.dataset.activeLearningPath;dialog.classList.remove('experience-detail-dialog');dialog.classList.toggle('contribution-dialog',wide);$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;if(!dialog.open)dialog.showModal();}
function notice(text){status('#toast',text);clearTimeout(notice.timer);notice.timer=setTimeout(()=>status('#toast',''),3500);}
function isSaved(kind,id){return savedItems.some(s=>s.kind===kind&&s.id===id);}
function saveButton(kind,item){const saved=isSaved(kind,item.id);return `<button type="button" class="icon-button save-button ${saved?'saved':''}" data-save="${esc(item.id)}" data-kind="${kind}" aria-label="${saved?'إلغاء حفظ':'حفظ'} ${esc(item.title||item.name)}" aria-pressed="${saved}" ${pendingSaves.has(accountVersion+':'+kind+':'+item.id)?'disabled':''}>${icon('bookmark')}</button>`;}
async function loadCatalog(){
 const version=++catalogVersion;
 ['opportunity','provider','experience'].forEach(k=>status('#'+k+'-state','جارٍ تحميل المحتوى…'));
 try{const result=await api.catalog();if(version!==catalogVersion)return;
  for(const key of ['opportunities','providers','experiences'])if(!Array.isArray(result?.[key]))throw new Error('تعذّر عرض المحتوى.');
  catalog={...catalog,...result};catalogReady=true;
  for(const key of ['opportunities','providers','experiences'])catalog[key]=catalog[key].filter(item=>!item.status||item.status==='published');
  catalog.interests=['الكل',...new Set([...(catalog.interests||[]).filter(x=>x!=='الكل'),...catalog.opportunities.flatMap(o=>o.fields||[])])];
  $('#interest-chips').innerHTML=catalog.interests.map(t=>`<button class="chip" data-interest="${esc(t)}" aria-pressed="false">${esc(t==='الكل'?'جميع المجالات':t)}</button>`).join('');
  for(const [id,key,label] of [['opportunity-type','type','جميع الأنواع'],['opportunity-mode','mode','الكل']]){const select=$('#'+id),value=select.value;select.replaceChildren(new Option(label,''));(key==='mode'?['عن بُعد','حضوري','حضوري وعن بُعد']:[...new Set(catalog.opportunities.map(o=>o[key]).filter(Boolean))]).forEach(v=>select.add(new Option(v,v)));select.value=value;if(select.selectedIndex<0)select.value='';}
  ['opportunity','provider','experience'].forEach(k=>status('#'+k+'-state',''));
  renderOpportunities();renderProviders();renderExperiences();if(!$('#content-page').hidden&&window.SaiContentPages.parse())window.SaiContentPages.render();
 }catch{if(version!==catalogVersion)return;$('#empty-opportunities').hidden=true;['opportunity','provider','experience'].forEach(k=>{$('#'+k+'-state').innerHTML='<div class="empty">تعذّر تحميل المحتوى. <button class="text-link" data-action="retry">إعادة المحاولة</button></div>';});}
}
function requireUser(action){if(user)return true;pendingAction=action;returnTo=location.hash.slice(1)||'home';location.hash='login';notice('سجّل دخولك للمتابعة، ثم نعيدك إلى ما اخترته.');return false;}
function syncAccount(){
 if(!user){$('#activity-followup').hidden=true;$('#activity-followup').replaceChildren();}
 $('#home-page').classList.toggle('member-home',!!user);
 $('#guest-home-title').hidden=!!user;$('#hero-description').hidden=!!user;
 $('#member-home-title').hidden=!user;$('#member-home-description').hidden=!user;
 $('#member-home-name').textContent=user?.name||'طالب';
 $('#member-daily-card').hidden=!user;$('#home-page .hero-emblem').hidden=!!user;
document.querySelectorAll('[data-guest-only]').forEach(el=>el.hidden=!!user);$('#profile-link').hidden=!user;$('#profile-display-name').textContent=user?.name||'طالب';window.SaiAvatar.paint($('.profile-mini-avatar'),user?.avatar,user?.name);$('#mobile-account-link').href=user?'#profile':'#login';$('#mobile-account-link').dataset.nav=user?'profile':'login';$('#mobile-account-label').textContent=user?'ملفي':'حسابي';$('#journey-link').hidden=!user;$('#saved-count').textContent=savedItems.length;$('#saved-count').hidden=!savedItems.length;}
async function toggleSave(kind,id,button){if(!requireUser(()=>toggleSave(kind,id)))return;const version=accountVersion,key=version+':'+kind+':'+id;if(pendingSaves.has(key))return;pendingSaves.add(key);const value=!isSaved(kind,id);if(button)button.disabled=true;try{await api.setSaved(kind,id,value);if(version!==accountVersion)return;savedItems=savedItems.filter(s=>!(s.kind===kind&&s.id===id));if(value)savedItems.push({kind,id});syncAccount();renderOpportunities();renderProviders();if(location.hash==='#saved')renderSaved();if(window.SaiContentPages.parse())window.SaiContentPages.render();notice(value?'أضيفت إلى محفوظاتك.':'أزيلت من المحفوظات.');}catch(error){if(version===accountVersion)notice(error.message||'تعذّر تحديث المحفوظات. حاول مرة أخرى.');}finally{pendingSaves.delete(key);document.querySelectorAll('[data-save]').forEach(el=>{if(el.dataset.kind===kind&&el.dataset.save===id)el.disabled=pendingSaves.has(accountVersion+':'+kind+':'+id);});}}
function renderSaved(){const content=$('#saved-content');content.innerHTML=savedItems.length?`<div class="card-grid">${savedItems.map(s=>{const item=(s.kind==='provider'?catalog.providers:catalog.opportunities).find(x=>x.id===s.id);return item?(s.kind==='provider'?providerCard(item):opportunityCard(item)):`<article class="card"><h3>هذا المحتوى غير متاح الآن</h3><button class="text-link" data-save="${esc(s.id)}" data-kind="${esc(s.kind)}">إزالة من المحفوظات</button></article>`;}).join('')}</div>`:'<div class="empty"><p>لم تحفظ شيئًا بعد.</p><a class="text-link" href="#opportunities">استكشف الفرص</a></div>';}
async function loadSaved(){const version=accountVersion;$('#saved-content').innerHTML='<p role="status">جارٍ تحميل المحفوظات…</p>';try{const result=await api.saved();if(version!==accountVersion)return;savedItems=result;syncAccount();renderSaved();}catch{$('#saved-content').innerHTML='<div class="empty">تعذّر تحميل المحفوظات. <button class="text-link" data-action="reload-saved">إعادة المحاولة</button></div>';}}
function contributionDialog(){if(!requireUser(contributionDialog))return;show('شارك تجربتك',`<form id="experience-form" class="platform-form"><p><strong>كيف بدأت؟</strong> ما التحدّي الذي واجهته؟ وما النصيحة التي تود مشاركتها؟</p><label for="experience-title">عنوان التجربة <span class="muted">(اختياري)</span></label><input id="experience-title" name="title" maxlength="120" value="${esc(experienceDraft.title)}"><label for="experience-topic">موضوع التجربة</label><select id="experience-topic" name="topic" required>${experienceOptions(experienceTopics,experienceDraft.topic,'اختر موضوع التجربة')}</select><label for="experience-field">المجال</label><select id="experience-field" name="field" required>${experienceOptions(experienceFields(),experienceDraft.field,'اختر المجال')}</select><label class="sr-only" for="experience-draft">نص التجربة</label><textarea id="experience-draft" name="body" rows="7" required minlength="30" maxlength="6000" placeholder="اكتب تجربتك هنا…">${esc(experienceDraft.body)}</textarea><label class="check-label"><input type="checkbox" required> أوافق على إرسال تجربتي للمراجعة قبل النشر.</label><p id="experience-feedback" class="form-feedback" role="status" hidden></p><button class="button" type="submit">إرسال للمراجعة</button></form>`,true);}
function validSignupPassword(value){return value.length>=8&&/[A-Z]/.test(value)&&/[a-z]/.test(value)&&/[0-9]/.test(value)&&/[^A-Za-z0-9\s]/.test(value);}
function setAuthMode(mode){if($('#login-form').hasAttribute('aria-busy'))return;authMode=mode;$('#password').removeAttribute('aria-invalid');$('#password').removeAttribute('aria-describedby');$('#login-form').reset();$('#password').type='password';$('#toggle-password').innerHTML=icon('eyeOff');$('#toggle-password').setAttribute('aria-pressed','false');$('#toggle-password').setAttribute('aria-label','إظهار كلمة المرور');$('#signup-name').hidden=mode!=='signup';$('#display-name').required=mode==='signup';$('#auth-password').hidden=mode==='reset';$('#password').required=mode!=='reset';$('#password').minLength=mode==='signup'?8:1;$('#password').autocomplete=mode==='signup'?'new-password':'current-password';$('#auth-title').textContent={login:'سعداء بعودتك.',signup:'ابدأ رحلتك مع سعي.',reset:'استعادة كلمة المرور'}[mode];$('#auth-submit').textContent={login:'تسجيل الدخول',signup:'إنشاء حساب',reset:'إرسال رابط الاستعادة'}[mode];$('#auth-mode-link').textContent=mode==='login'?'جديد في سعي؟ أنشئ حسابك':'لديك حساب؟ تسجيل الدخول';status('#auth-feedback','');}
async function formRequest(form,feedback,operation){
 const button=form.querySelector('[type="submit"]');if(button.disabled)return;
 const version=accountVersion,owner=user?.id,revision=dialog.dataset.revision,inDialog=dialog.contains(form),message=form.querySelector(feedback);
 const current=()=>form.isConnected&&version===accountVersion&&owner===user?.id&&(!inDialog||(dialog.open&&dialog.dataset.revision===revision));
 const showFeedback=(text,error=false)=>{if(!message||!current())return;message.hidden=!text;message.textContent=text;message.classList.toggle('is-error',error);};
 const authButtons=form.id==='login-form'?[$('#auth-mode-link'),$('#google-login')].map(el=>({el,disabled:el.disabled})):[];authButtons.forEach(({el})=>el.disabled=true);
 const controls=[...form.querySelectorAll('input,textarea,select,button:not([type=submit])')].map(el=>({el,inert:el.inert}));controls.forEach(({el})=>el.inert=true);
 button.disabled=true;form.setAttribute('aria-busy','true');showFeedback('جارٍ تنفيذ طلبك…');
 try{await operation(current);}catch(error){showFeedback(error.message||'تعذّر إكمال الطلب. حاول مرة أخرى.',true);}finally{authButtons.forEach(({el,disabled})=>el.disabled=disabled);controls.forEach(({el,inert})=>el.inert=inert);button.disabled=false;form.removeAttribute('aria-busy');}
}
async function authenticate(event){event.preventDefault();if($('#google-login').disabled)return;const form=event.currentTarget;const passwordInput=$('#password');if(authMode==='signup'&&!validSignupPassword(passwordInput.value)){status('#auth-feedback','كلمة المرور يجب أن تكون 8 خانات على الأقل، وتشمل حرفًا إنجليزيًا كبيرًا وحرفًا صغيرًا ورقمًا ورمزًا.',true);passwordInput.setAttribute('aria-invalid','true');passwordInput.setAttribute('aria-describedby','auth-feedback');passwordInput.focus();return;}passwordInput.removeAttribute('aria-invalid');passwordInput.removeAttribute('aria-describedby');if(!form.reportValidity())return;await formRequest(form,'#auth-feedback',async()=>{const email=$('#email').value.trim(),password=$('#password').value;if(authMode==='reset'){await api.resetPassword(email);status('#auth-feedback','إذا كان البريد مسجّلًا، سيصلك رابط لاستعادة كلمة المرور.');return;}if(authMode==='signup'){if(!$('#display-name').value.trim())throw new Error('أدخل اسمك.');await api.signup({name:$('#display-name').value.trim(),email,password});form.removeAttribute('aria-busy');setAuthMode('login');status('#auth-feedback','إذا كان البريد صالحًا للتسجيل، ستصلك رسالة تحقق. افتحها في هذا المتصفح ثم سجّل الدخول.');return;}const result=await api.login({email,password});if(!result?.id)throw new Error('تعذّر التحقق من تسجيل الدخول.');user=result;accountVersion++;try{savedItems=await api.saved();}catch{savedItems=[];}syncAccount();const next=pendingAction;pendingAction=null;location.hash=returnTo==='login'?'home':returnTo;setTimeout(()=>next?.(),0);});$('#password').value='';}
function input(label,name,value='',type='text'){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" maxlength="200"></label>`;}
async function loadProfile(){const version=accountVersion;$('#profile-content').innerHTML='<p role="status">جارٍ تحميل ملفك…</p>';try{const [p,experiences]=await Promise.all([api.profile(),api.myExperiences()]);if(version!==accountVersion)return;$('#profile-content').innerHTML=`<div class="profile-layout"><aside class="profile-summary"><div class="profile-avatar">${esc((p.name||user.name||'س').slice(0,1))}</div><h2>${esc(p.name||user.name||'ملفي')}</h2><nav class="profile-summary-actions" aria-label="روابط الحساب"><a class="button outline" href="#journey">خطوتك القادمة</a>${user.role==='admin'?'<a class="button outline" href="#admin">إدارة المحتوى</a>':''}</nav></aside><div class="profile-content"><section class="profile-panel"><h2>بياناتي</h2><form id="profile-form" class="platform-form">${input('الاسم','name',p.name||user.name)}${input('اهتماماتي (افصل بينها بفاصلة)','interests',(p.interests||[]).join('، '))}<p class="form-feedback" id="profile-feedback" role="status" hidden></p><button type="submit" class="button">حفظ التعديلات</button></form></section><section class="profile-panel"><h2>تجاربي</h2>${experiences.length?experiences.map(e=>`<details class="profile-experience"><summary><span class="profile-experience-title">${esc(e.title||'تجربتي')}</span><span class="profile-experience-meta"><span class="badge">${esc(e.topic||'تجربة أخرى')}</span><span class="badge profile-experience-status">${esc({pending:'قيد المراجعة',published:'منشورة',rejected:'تحتاج تعديلًا'}[e.status]||'قيد المراجعة')}</span></span><span class="profile-experience-toggle" aria-hidden="true">+</span></summary><div class="profile-experience-body"><div class="experience-detail-copy">${paragraphs(e.body)}</div></div></details>`).join(''):'<p class="muted">لم ترسل تجربة بعد.</p>'}<button class="text-link" data-action="contribute">شارك تجربتك</button></section></div></div>`;$('#profile-form [name="name"]').required=true;window.SaiAvatar.mount(p);}catch{$('#profile-content').innerHTML='<div class="empty">تعذّر تحميل ملفك. <button class="text-link" data-action="reload-profile">إعادة المحاولة</button></div>';}}
function renderAdmin(){window.SaiOwnerConsole.render();}
const titles={home:'مساحة لخطوتك القادمة',opportunities:'الفرص',learning:'جهات التعلم',experiences:'تجارب الطلاب',login:'تسجيل الدخول',profile:'ملفي',saved:'المحفوظات',journey:'خطوتك القادمة',admin:'إدارة المحتوى',content:'التفاصيل'};
function route(){window.SaiContentPages.remember();const contentRoute=window.SaiContentPages.parse();let target=contentRoute?'content':location.hash.slice(1)||'home';if(target==='main'){$('#main').focus();return;}if(!Object.hasOwn(titles,target)){target='home';history.replaceState(null,'','#home');}if(['profile','saved','admin','journey'].includes(target)&&!user){returnTo=target;target='login';history.replaceState(null,'','#login');}document.querySelectorAll('[data-page]').forEach(p=>p.hidden=p.dataset.page!==target);document.querySelectorAll('[data-nav]').forEach(a=>{const selected=a.dataset.nav===(contentRoute?.section||target);a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(dialog.open)dialog.close();document.title='سعي | '+titles[target];window.scrollTo({top:0,behavior:'instant'});const heading=$(`[data-page="${target}"] h1`);if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}if(target==='saved')loadSaved();if(target==='profile')loadProfile();if(target==='admin')renderAdmin();if(target==='journey')window.SaiStudentJourney.render();if(target==='content')window.SaiContentPages.render();else window.SaiContentPages.restore();}
document.addEventListener('click',async event=>{const el=event.target.closest('button');if(!el)return;const d=el.dataset;if(d.interest){activeInterest=d.interest;renderOpportunities();return;}if(d.save){await toggleSave(d.kind,d.save,el);return;}if(d.detail){openOpportunity(d.detail);return;}if(d.provider){openProvider(d.provider);return;}if(d.experience){const e=catalog.experiences.find(x=>x.id===d.experience);if(e){show(e.title||'تجربة طالب',experienceDetail(e));dialog.classList.add('experience-detail-dialog');window.SaiStudentJourney.attach('experience',e);}return;}switch(d.action){case 'retry':loadCatalog();break;case 'contribute':contributionDialog();break;case 'saved':location.hash='saved';break;case 'reload-saved':loadSaved();break;case 'reload-profile':loadProfile();break;case 'signup':setAuthMode(authMode==='login'?'signup':'login');break;case 'forgot':setAuthMode('reset');break;case 'logout':el.disabled=true;try{await api.logout();accountVersion++;window.SaiOwnerConsole?.clear();user=null;savedItems=[];pendingAction=null;experienceDraft={title:'',body:'',field:'',topic:''};$('#profile-content').replaceChildren();$('#saved-content').replaceChildren();$('#journey-content').replaceChildren();syncAccount();renderOpportunities();renderProviders();location.hash='home';}catch(error){notice(error.message);}finally{el.disabled=false;}break;}});
document.addEventListener('input',event=>{if(event.target.closest('#experience-form'))experienceDraft=Object.fromEntries(new FormData($('#experience-form')));});
document.addEventListener('submit',async event=>{const form=event.target;if(!['experience-form','profile-form'].includes(form.id))return;event.preventDefault();if(!user||!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));const split=value=>String(value||'').split(/[,،]/).map(s=>s.trim()).filter(Boolean);
 if(form.id==='experience-form'){if(values.body.trim().length<30){status('#experience-feedback','اكتب تجربة من 30 حرفًا على الأقل.',true);return;}const author=user.id,version=accountVersion;await formRequest(form,'#experience-feedback',async current=>{await api.submitExperience({...values,body:values.body.trim()});if(user?.id!==author||version!==accountVersion)return;if(['title','body','field','topic'].every(key=>(experienceDraft[key]||'')===(values[key]||'')))experienceDraft={title:'',body:'',field:'',topic:''};if(!current()){notice('تم إرسال تجربتك للمراجعة.');return;}show('وصلتنا تجربتك','<p>تجربتك قيد المراجعة، وستظهر للعامة بعد اعتمادها.</p><a class="button outline" href="#profile">متابعة الحالة في ملفي</a>');});}
 if(form.id==='profile-form')await formRequest(form,'#profile-feedback',async current=>{if(!values.name.trim())throw new Error('أدخل اسمك.');await api.updateProfile({name:values.name.trim(),interests:split(values.interests)});if(!current())return;user.name=values.name.trim();syncAccount();$('.profile-summary h2').textContent=user.name;window.SaiAvatar.paint($('.profile-avatar'),user.avatar,user.name);status('#profile-feedback','تم حفظ تعديلاتك.');});
});
$('#google-login').addEventListener('click',async()=>{
 const button=$('#google-login');if(button.disabled||$('#login-form').hasAttribute('aria-busy'))return;button.disabled=true;$('#auth-submit').disabled=true;$('#auth-mode-link').disabled=true;
 status('#google-feedback','جارٍ الانتقال إلى Google…');
 try{sessionStorage.setItem('sai-google-return',['home','opportunities','learning','experiences','saved','profile','journey'].includes(returnTo)||window.SaiContentPages.parse('#'+returnTo)?returnTo:'home');await api.loginGoogle();}
 catch(error){sessionStorage.removeItem('sai-google-return');status('#google-feedback',error.message||'تعذّر الدخول بجوجل. حاول مجددًا.',true);button.disabled=false;$('#auth-submit').disabled=false;$('#auth-mode-link').disabled=false;}
});
$('#login-form').addEventListener('submit',authenticate);
$('#password').addEventListener('input',()=>{if($('#password').hasAttribute('aria-invalid')&&validSignupPassword($('#password').value)){$('#password').removeAttribute('aria-invalid');$('#password').removeAttribute('aria-describedby');status('#auth-feedback','');}});
$('#toggle-password').onclick=function(){const visible=$('#password').type==='password';$('#password').type=visible?'text':'password';this.innerHTML=icon(visible?'eye':'eyeOff');this.setAttribute('aria-pressed',String(visible));this.setAttribute('aria-label',visible?'إخفاء كلمة المرور':'إظهار كلمة المرور');};
$('#close-dialog').onclick=()=>dialog.close();
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
$('.skip').onclick=event=>{event.preventDefault();$('#main').focus();};
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
(async()=>{await Promise.all([loadCatalog(),(async()=>{try{user=await api.session();if(user)savedItems=await api.saved();}catch{notice('تعذّر التحقق من الحساب. يمكنك متابعة التصفح والمحاولة مجددًا.');}})()]);document.body.removeAttribute('data-booting');$('#boot-status').hidden=true;const googleReturn=sessionStorage.getItem('sai-google-return');
 if(googleReturn){sessionStorage.removeItem('sai-google-return');if(user&&(['home','opportunities','learning','experiences','saved','profile','journey'].includes(googleReturn)||window.SaiContentPages.parse('#'+googleReturn)))location.hash=googleReturn;else if(!user){location.hash='login';status('#google-feedback','لم يكتمل الدخول بجوجل. يمكنك المحاولة مجددًا.',true);}}
 syncAccount();if(catalogReady){renderOpportunities();renderProviders();}window.addEventListener('hashchange',route);route();try{if(await api.recoveryRequired?.())passwordRecoveryDialog();}catch{notice('تعذّر التحقق من رابط الاستعادة. اطلب رابطًا جديدًا من تسجيل الدخول.');}})();

function passwordRecoveryDialog(){
 show('تعيين كلمة مرور جديدة',`<form id="password-recovery-form" class="platform-form"><label>كلمة المرور الجديدة<input name="password" type="password" autocomplete="new-password" minlength="8" maxlength="200" required></label><label>تأكيد كلمة المرور<input name="confirmation" type="password" autocomplete="new-password" minlength="8" maxlength="200" required></label><p>استخدم 8 خانات على الأقل، تشمل حرفًا إنجليزيًا كبيرًا وصغيرًا ورقمًا ورمزًا.</p><p id="recovery-feedback" class="form-feedback" role="status" hidden></p><button class="button" type="submit">حفظ كلمة المرور</button></form>`);
 $('#password-recovery-form').addEventListener('submit',async event=>{
  event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;
  const values=Object.fromEntries(new FormData(form));if(!validSignupPassword(values.password)){status('#recovery-feedback','استخدم 8 خانات على الأقل، تشمل حرفًا إنجليزيًا كبيرًا وصغيرًا ورقمًا ورمزًا.',true);return;}if(values.password!==values.confirmation){status('#recovery-feedback','كلمتا المرور غير متطابقتين.',true);return;}
  await formRequest(form,'#recovery-feedback',async()=>{await api.changePassword(values.password);form.reset();dialog.close();setAuthMode('login');location.hash='login';status('#auth-feedback','تم تغيير كلمة المرور. سجّل الدخول بكلمة المرور الجديدة.');});
 });
}
window.addEventListener('sai:signout',()=>{
 accountVersion++;window.SaiOwnerConsole?.clear();user=null;savedItems=[];pendingAction=null;experienceDraft={title:'',body:'',field:'',topic:''};
 $('#profile-content').replaceChildren();$('#saved-content').replaceChildren();$('#journey-content').replaceChildren();$('#admin-content').replaceChildren();
 if(dialog.open)dialog.close();syncAccount();if(catalogReady){renderOpportunities();renderProviders();}route();
});
